const POINTS = [
  'Singapore HQ, serving Singapore & India',
  'Live product with real audits and real posts',
  'Founder-led onboarding for early customers',
];

export default function Beta() {
  return (
    <section id="beta" style={{ background: 'var(--white)', borderTop: '1px solid var(--border)' }}>
      <div className="wrap">
        <div className="head center">
          <span className="eyebrow">Where we are</span>
          <h2>Built for the first wave of AI-search-native brands.</h2>
          <p>
            AEO-APP.AI launched in beta in August 2026 and already works with paying customers in
            Singapore and India.
          </p>
        </div>
        <ul style={{ marginTop: 32, maxWidth: 520, marginInline: 'auto', display: 'flex', flexDirection: 'column', gap: 12 }}>
          {POINTS.map((text) => (
            <li key={text} style={{ fontSize: 14.5, color: 'var(--slate)', textAlign: 'center' }}>{text}</li>
          ))}
        </ul>
        <p style={{ marginTop: 22, fontSize: 13, fontStyle: 'italic', color: 'var(--slate-light)', textAlign: 'center' }}>
          Add a verified customer result or statistic when available.
        </p>
      </div>
    </section>
  );
}
